#include <iostream>

// Swaps values in memory pointed to by p1 and p2 (passed by value)
void swapValues(int* p1, int* p2) {
    int temp = *p1;
    *p1 = *p2;
    *p2 = temp;
}

// Swaps where the pointers p1 and p2 point to (passed by reference)
void swapPointers(int*& p1, int*& p2) {
    int* temp = p1;
    p1 = p2;
    p2 = temp;
}

int main() {
    int a = 10;
    int b = 20;
    int* ptrA = &a;
    int* ptrB = &b;

    std::cout << "Initial values: a=" << a << ", b=" << b << std::endl;
    std::cout << "Initial dereference: *ptrA=" << *ptrA << ", *ptrB=" << *ptrB << std::endl;

    // 1. Swap values in place
    swapValues(ptrA, ptrB);
    std::cout << "After swapValues: a=" << a << ", b=" << b << std::endl;
    std::cout << "Pointers still point to same variables: *ptrA=" << *ptrA << ", *ptrB=" << *ptrB << std::endl;

    // 2. Swap pointer targets
    swapPointers(ptrA, ptrB);
    std::cout << "After swapPointers: a=" << a << ", b=" << b << std::endl;
    std::cout << "Pointer targets swapped: *ptrA=" << *ptrA << ", *ptrB=" << *ptrB << std::endl;

    return 0;
}

