#include <iostream>

// Reverses array in-place and returns pointer to the first element
int* reverseArray(int* list, int size) {
    for (int i = 0, j = size - 1; i < j; ++i, --j) {
        int temp = list[j];
        list[j] = list[i];
        list[i] = temp;
    }
    return list;
}

// Prints array elements using pointer to const data
void printArray(const int* list, int size) {
    for (int i = 0; i < size; ++i) {
        std::cout << list[i] << (i + 1 < size ? " " : "\n");
    }
}

int main() {
    int numbers[] = {11, 22, 33, 44, 55, 66};
    const int size = sizeof(numbers) / sizeof(numbers[0]);

    std::cout << "Original array: ";
    printArray(numbers, size);

    int* result = reverseArray(numbers, size);
    std::cout << "Reversed array: ";
    printArray(result, size);

    std::cout << "Result matches original base: " << (result == numbers ? "true" : "false") << std::endl;

    return 0;
}
